// Health-record status, severity and provider have no backend columns yet, so they travel as a
// labelled first line of the summary. Mirrors web/src/pages/records/recordSummaryMeta.ts.
class RecordSummaryMeta {
  const RecordSummaryMeta({
    this.status = '',
    this.severity = '',
    this.doctor = '',
    this.cleanSummary = '',
  });

  static const statuses = ['Active', 'Resolved', 'Inactive', 'Chronic'];
  static const severities = ['Mild', 'Moderate', 'Severe'];

  static final _part = RegExp(
    r'^(Status|Severity|Doctor|Provider):\s*(.+)$',
    caseSensitive: false,
  );

  /// Only a first line made up entirely of labelled parts counts as metadata.
  factory RecordSummaryMeta.parse(String? summary) {
    final text = (summary ?? '').trim();
    if (text.isEmpty) return const RecordSummaryMeta();
    final lines = text.split('\n');
    final matches = lines.first
        .split('·')
        .map((part) => _part.firstMatch(part.trim()))
        .toList(growable: false);
    if (matches.any((match) => match == null)) {
      return RecordSummaryMeta(cleanSummary: text);
    }
    var status = '';
    var severity = '';
    var doctor = '';
    for (final match in matches) {
      final key = match!.group(1)!.toLowerCase();
      final value = match.group(2)!.trim();
      if (key == 'status') {
        status = value;
      } else if (key == 'severity') {
        severity = value;
      } else {
        doctor = value;
      }
    }
    return RecordSummaryMeta(
      status: status,
      severity: severity,
      doctor: doctor,
      cleanSummary: lines.skip(1).join('\n').trim(),
    );
  }

  final String status;
  final String severity;
  final String doctor;
  final String cleanSummary;

  static String _clean(String value) =>
      value.replaceAll(RegExp(r'[·\r\n]+'), ' ').replaceAll(RegExp(r'\s+'), ' ').trim();

  /// "Status: Active · Severity: Mild · Doctor: Dr. X", or empty when nothing is set.
  String get metaLine => [
    if (_clean(status).isNotEmpty) 'Status: ${_clean(status)}',
    if (_clean(severity).isNotEmpty) 'Severity: ${_clean(severity)}',
    if (_clean(doctor).isNotEmpty) 'Doctor: ${_clean(doctor)}',
  ].join(' · ');

  String format() => [
    if (metaLine.isNotEmpty) metaLine,
    if (cleanSummary.trim().isNotEmpty) cleanSummary.trim(),
  ].join('\n');
}
